pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _unusedFuzz) public {
        // Any call to version() with no arguments must return exactly "1.0.0"
        string memory v = c.version();
        bytes32 vHash = keccak256(bytes(v));
        bytes32 expectedHash = keccak256(bytes("1.0.0"));
        assertTrue(vHash == expectedHash);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, uint64 newNumber) external {
        require(caller != c.DEPOSITOR_ACCOUNT());
        uint64 oldNumber = c.number();
        (bool success,) = address(c).call(abi.encodeWithSignature("setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)", newNumber, uint64(0), uint256(0), bytes32(0), uint64(0), bytes32(0), uint256(0), uint256(0)));
        if (success) {
            assert(c.number() == oldNumber);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        bool reverted;
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setL1BlockValues.selector, _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar));
        reverted = !ok;
        assert(reverted == true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(true);
        bool reverted;
